styles.tutorial:
section[data-skill-hub] .-w {
  display: grid;
  grid-template-columns: repeat(28, 1fr);
  align-items: center;
  column-gap: var(--g-gap);
  min-height: calc(var(--vh,1vh) * 100);
  perspective: 80rem;
}
section[data-skill-hub] figure {
  grid-row-start: 1;
  grid-row-end: 2;
  transform: translate(calc(var(--magnetic-x) * 0.5%), calc(var(--magnetic-y) * 0.5%)) rotateX(calc(var(--magnetic-y) * -0.5deg)) rotateY(calc(var(--magnetic-x) * 0.5deg));
  scale: 0.9;
  translate: 0 0;
  rotate: 0deg;
  transition: scale 0.6s var(--easing-function), rotate 0.6s var(--easing-function), translate 0.6s var(--easing-function);
}

section[data-skill-hub] .image-1 {
  grid-column-start: 3;
  grid-column-end: 12;
  translate: 0 -5%;
  rotate: -5deg;
}
section[data-skill-hub] .image-2 {
  grid-column-start: 10;
  grid-column-end: 20;
  position: relative;
  z-index: 20;
  translate: 0 0;
  rotate: 5deg;
}
section[data-skill-hub] .image-3 {
  grid-column-start: 18;
  grid-column-end: 27;
  translate: 0 10%;
  rotate: 10deg;
}

@media (min-width: 1024px) {
  section[data-skill-hub] figure:hover {
    transition: scale 0.6s var(--easing-function-2), rotate 0.6s var(--easing-function-2), translate 0.6s var(--easing-function-2);
  }
  section[data-skill-hub] .image-1 {
    grid-column-start: 7;
    grid-column-end: 13;
  }
  section[data-skill-hub] .image-2 {
    grid-column-start: 12;
    grid-column-end: 18;
  }
  section[data-skill-hub] .image-3 {
    grid-column-start: 17;
    grid-column-end: 23;
}
  section[data-skill-hub] .-w:has(figure:hover) .image-1 {
    translate: -5% 5%;
    rotate: 5deg;
  }
  section[data-skill-hub] .-w:has(figure:hover) .image-2 {
    translate: 0 -10%;
    rotate: 0deg;
  }
  section[data-skill-hub] .-w:has(figure:hover) .image-3 {
    translate: 5% 0%;
    rotate: -5deg;
  }
  section[data-skill-hub] .-w:has(figure:hover) figure {
    scale: 0.8;
    transition: scale 0.3s var(--easing-function-2), rotate 0.3s var(--easing-function-2), translate 0.3s var(--easing-function-2);
  }
  section[data-skill-hub] .-w:has(figure:hover) figure:hover {
    scale: 1;
  }
}
section[data-skill-hub] .note {
  grid-row-start: 1;
  grid-row-end: 2;
  grid-column-start: 1;
  grid-column-end: 29;
  justify-self: center;
  position: relative;
  z-index: 30;
  pointer-events: none;
}
